import numpy as np, scipy.optimize as so
def base(q):
    c,d,m,l,n2=q
    B=[np.ones_like(eps),T**2*np.sqrt(eps),1/eps,T*eps**m,np.exp(-l*eps),T,T**c*eps**d,T**n2*np.exp(-l*eps)]
    return np.column_stack(B)
def loss(q):
    X=base(q)
    c=np.linalg.lstsq(X,sigma,rcond=None)[0]
    return np.mean((sigma-X@c)**2)/np.var(sigma)
